/* ══ УТИЛИТЫ ══ */
const f=n=>{const a=Math.abs(n);if(a>=1e9)return(n/1e9).toFixed(2)+" млрд";if(a>=1e6)return(n/1e6).toFixed(1)+" млн";if(a>=1e3)return(n/1e3|0)+"тыс";return(n|0)+""};
const fr=n=>f(n)+" ₽";
const fk=n=>n>=1000?(n/1000).toFixed(1)+" т":(n|0)+" кг";
const pct=(a,b)=>b>0?Math.round(a/b*100):999;

