/* ══ UI КОМПОНЕНТЫ ══ */
const Sl=({l,v,min,max,step=1,set,suf,n})=>(<div style={{marginBottom:12}}><div style={{display:"flex",justifyContent:"space-between",fontSize:12,color:C.dim,marginBottom:3}}><span>{l}</span><span style={{color:C.text,fontWeight:600}}>{typeof suf==="function"?suf(v):`${v}${suf||""}`}</span></div><input type="range" min={min} max={max} step={step} value={v} onChange={e=>set(+e.target.value)} style={{width:"100%",accentColor:C.grn,height:5}}/>{n&&<div style={{fontSize:11,color:C.dim,marginTop:2}}>{n}</div>}</div>);
const Rw=({l,v,h,c,unit})=>(<div style={{display:"flex",justifyContent:"space-between",padding:"4px 0",borderBottom:`1px solid ${C.border}`,fontSize:13,fontWeight:h?600:400}}><span style={{color:c||C.dim}}>{l}</span><span style={{color:h?C.text:C.dim}}>{unit==="kg"?fk(v):unit==="pcs"?(v>=1000?(v/1000).toFixed(1)+"тыс шт":v+" шт"):fr(v)}</span></div>);
const Tag=({v,ok=true})=>(<span style={{fontSize:11,fontWeight:600,borderRadius:4,padding:"2px 8px",background:ok?C.grn2:C.red2,color:ok?C.grn:C.red}}>{v}</span>);
const Cd=({t,v,sub,ok=true})=>(<div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:10,padding:"12px 16px",boxShadow:"0 1px 3px rgba(0,0,0,0.04)"}}><div style={{fontSize:11,color:C.dim,marginBottom:2}}>{t}</div><div style={{fontSize:18,fontWeight:700,color:ok?C.grn:C.red}}>{v}</div>{sub&&<div style={{fontSize:11,color:C.dim,marginTop:2}}>{sub}</div>}</div>);
const Badge=({l,v})=>(<span style={{background:"#f0eeea",borderRadius:6,padding:"4px 10px",fontSize:12,color:C.text,display:"inline-block",marginRight:6,marginBottom:4}}><span style={{color:C.dim}}>{l}: </span><strong>{v}</strong></span>);
const Section=({title})=>(<div style={{fontSize:13,fontWeight:700,color:C.h,marginTop:14,marginBottom:8,borderBottom:`2px solid ${C.border}`,paddingBottom:4}}>{title}</div>);
const Bar=({label,pct:p,sub})=>(<div style={{marginBottom:8}}><div style={{display:"flex",justifyContent:"space-between",fontSize:12}}><span style={{color:C.dim}}>{label}</span><Tag v={`${p}%`} ok={p>=100}/></div><div style={{width:"100%",height:5,background:"#e5e3dc",borderRadius:3,marginTop:3}}><div style={{width:`${Math.min(p,100)}%`,height:5,borderRadius:3,background:p>=100?C.grn:p>=50?C.gold:C.red}}/></div>{sub&&<div style={{fontSize:11,color:C.dim,marginTop:1}}>{sub}</div>}</div>);
const DC=({nm,cx,op,rv,bl,ok=true})=>(<div style={{background:C.card,border:`1px solid ${ok===false?C.red:C.border}`,borderRadius:10,padding:"12px 16px",boxShadow:"0 1px 3px rgba(0,0,0,0.04)"}}><div style={{fontSize:12,fontWeight:600,color:ok===false?C.red:C.dim,marginBottom:6}}>{nm}{ok===false&&" ⚠"}</div><div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:4,fontSize:12}}><div><span style={{color:C.dim}}>Capex</span><div style={{fontWeight:600}}>{f(cx)}</div></div><div><span style={{color:C.dim}}>Opex</span><div style={{color:C.red}}>{f(op)}</div></div><div><span style={{color:C.dim}}>Баланс</span><div style={{color:bl>=0?C.grn:C.red,fontWeight:700}}>{bl>=0?"+":""}{f(bl)}</div></div></div></div>);

const Desc=({text,open=true})=>{const[o,setO]=useState(open);return(<div style={{marginBottom:14}}><button onClick={()=>setO(!o)} style={{background:"none",border:"none",cursor:"pointer",fontSize:12,color:C.grn,fontWeight:600,padding:0,display:"flex",alignItems:"center",gap:4}}><span style={{fontSize:10}}>{o?"▾":"▸"}</span>{o?"Свернуть":"О домене"}</button>{o&&<div style={{background:C.grn2,border:"1px solid #c6e4cd",borderRadius:8,padding:14,marginTop:6,fontSize:12,color:"#1a5c32",lineHeight:1.7,whiteSpace:"pre-wrap"}}>{text}</div>}</div>);};

